using System.Collections.Generic;using UnityEngine;using UnityEngine.XR;using LighthouseKeepers.Core;
namespace LighthouseKeepers.WatchDemo {
 [DefaultExecutionOrder(1500)]public sealed class QuestRenderQuality:MonoBehaviour {
  WatchBeacon beacon;readonly List<Light> lights=new();readonly List<XRDisplaySubsystem> displays=new();readonly HashSet<Light> handLanterns=new();float nextScan;bool enforceLights;
  public static void Create(WatchDemoController watch){var s=VisualPassSettings.Current;if(!s||!s.renderQuality)return;watch.gameObject.AddComponent<QuestRenderQuality>();}
  void Start(){enforceLights=Resources.Load<TextAsset>("VisualLightingReady")!=null;beacon=FindAnyObjectByType<WatchBeacon>();foreach(var camera in FindObjectsByType<Camera>(FindObjectsSortMode.None)){camera.nearClipPlane=.04f;camera.useOcclusionCulling=false;camera.allowMSAA=true;}SubsystemManager.GetSubsystems(displays);foreach(var display in displays){display.foveatedRenderingFlags=XRDisplaySubsystem.FoveatedRenderingFlags.None;display.foveatedRenderingLevel=VisualPassSettings.Current.fixedFoveation;}}
  void LateUpdate(){if(!enforceLights)return;if(Time.time>=nextScan){nextScan=Time.time+2;lights.Clear();lights.AddRange(FindObjectsByType<Light>(FindObjectsInactive.Include,FindObjectsSortMode.None));handLanterns.Clear();foreach(var lamp in FindObjectsByType<WatchLantern>(FindObjectsSortMode.None)){var pool=lamp.GetComponentInChildren<Light>(true);if(pool&&pool.shadows==LightShadows.None&&handLanterns.Count<2)handLanterns.Add(pool);}}int burning=0;foreach(var lamp in handLanterns)if(lamp&&lamp.enabled)burning++;if(beacon)beacon.lantern.enabled=beacon.Lit&&handLanterns.Count==0;foreach(var light in lights)if(light&&light.enabled&&(!beacon||light!=beacon.lantern)&&!handLanterns.Contains(light))light.enabled=false;}
 }
}